python3 -B -I - <<'EOF'
import re
for fname in ("steps-01-08/train.stdout", "steps-09-30/train.stdout"):
    with open(fname, "rb") as fh:
        text = fh.read().decode("utf-8", "replace")
    text = re.sub(r"\x1b\[[0-9;]*m", "", text)
    print("=====", fname)
    m = re.findall(r"step:(\d+) - (.*)$", text, re.M)
    for n, body in m:
        d = {}
        for part in body.split(" - "):
            if ":" in part:
                k, v = part.split(":", 1)
                d[k.strip()] = v.strip()
        print(n, "advantages:", {k: d.get(k, "?") for k in d if "advantage" in k or k.startswith("actor/loss") or k.startswith("critic/score")})
EOF

