arguments.command:
python3 -B -I - <<'EOF'
import json
from collections import defaultdict
print("E0 → E8: per-question correct-count change")
for name, prev in (("E8.json","E0.json"), ("E30.json","E8.json")):
    cur = json.load(open(f"evidence/evaluation/{name}"))
    old = json.load(open(f"evidence/evaluation/{prev}"))
    cq = {p["index"]: sum(s["correct"] for s in p["samples"]) for p in cur["predictions"]}
    oq = {p["index"]: sum(s["correct"] for s in p["samples"]) for p in old["predictions"]}
    for i in sorted(cq):
        d = cq[i]-oq[i]
        if d: print(f"  q{i}: {oq[i]} -> {cq[i]} ({d:+d})")
    print(f"  ({prev}->{name} done)")
EOF

